from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    # Filter out cancelled rows
    df_active = df[df['row_kind'] != 'cancelled'].copy()

    # Parse dates
    for col in ['Delivered Date', 'Requested Date']:
        df_active[col] = pd.to_datetime(df_active[col], errors='coerce')

    # Determine last date in data
    last_date = df_active['Delivered Date'].max()

    # Define delivered status set
    delivered_statuses = {'delivered'}
    in_transit_statuses = {
        'in transit', 'out for delivery', 'picked up', 'exception',
        'delivery exception', 'delayed', 'tendered', 'booked', 'dispatched',
        'pending', 'shipped', 'partially shipped', 'backordered',
        'short shipped', 'open', 'allocated', 'released', 'picked', 'packed'
    }

    df_active['status_lower'] = df_active['Status'].str.lower().str.strip()

    # OTIF (order) denominator: distinct orders where delivered on time OR in transit
    # Condition: days_before_promise >= 0 (delivered on or before promise)
    #            OR days_late > 0 (delivered late)
    #            OR (days_past_due > 0 AND status in in_transit_statuses)
    denom_mask = (
        (df_active['days_before_promise'] >= 0) |
        (df_active['days_late'] > 0) |
        ((df_active['days_past_due'] > 0) & (df_active['status_lower'].isin(in_transit_statuses)))
    )

    # Numerator: orders in denominator MINUS orders that fail OTIF
    # Fail = (days_late > 0) OR (shipped_minus_ordered < 0 AND days_before_promise >= 0)
    #        OR (days_past_due > 0 AND status in in_transit_statuses) [not yet delivered = not OTIF]
    fail_mask = (
        (df_active['days_late'] > 0) |
        ((df_active['shipped_minus_ordered'] < 0) & (df_active['days_before_promise'] >= 0)) |
        ((df_active['days_past_due'] > 0) & (df_active['status_lower'].isin(in_transit_statuses)))
    )

    # Per warehouse OTIF (order level)
    otif_results = []
    warehouses = df_active['Warehouse'].dropna().unique()

    for wh in warehouses:
        wh_df = df_active[df_active['Warehouse'] == wh]

        # Denominator orders
        denom_orders = wh_df[denom_mask.reindex(wh_df.index, fill_value=False)]['Order ID'].nunique()

        # Failing orders (any line fails = order fails)
        fail_orders_set = set(wh_df[fail_mask.reindex(wh_df.index, fill_value=False)]['Order ID'].unique())
        denom_orders_set = set(wh_df[denom_mask.reindex(wh_df.index, fill_value=False)]['Order ID'].unique())

        otif_orders = len(denom_orders_set - fail_orders_set)
        otif_rate = otif_orders / denom_orders if denom_orders > 0 else float('nan')
        otif_results.append({"name": str(wh), "value": round(otif_rate, 6)})

    # Sort by value descending
    otif_results.sort(key=lambda x: x['value'] if not (x['value'] != x['value']) else -1, reverse=True)

    result['segments'].append({
        "segment_column": "Warehouse",
        "metric_column": "Order ID",
        "aggregation": "ratio",
        "label": "otif_order",
        "results": otif_results
    })

    # Also compute overall OTIF (order) for reference
    denom_orders_all = df_active[denom_mask]['Order ID'].nunique()
    fail_orders_all = set(df_active[fail_mask]['Order ID'].unique())
    denom_orders_all_set = set(df_active[denom_mask]['Order ID'].unique())
    otif_all = len(denom_orders_all_set - fail_orders_all) / denom_orders_all if denom_orders_all > 0 else float('nan')

    result['segments'].append({
        "segment_column": "Warehouse",
        "metric_column": "Order ID",
        "aggregation": "ratio",
        "label": "otif_order_overall",
        "results": [{"name": "All Warehouses", "value": round(otif_all, 6)}]
    })

    result['assumptions'].append("OTIF (order): an order passes only when ALL its delivered lines are on-time AND shipped in full; in-transit orders count in denominator but not numerator.")
    result['assumptions'].append("Cancelled rows (row_kind='cancelled') excluded from all calculations.")
    result['assumptions'].append("days_before_promise, days_late, days_past_due, shipped_minus_ordered used as provided; not recomputed.")

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

