    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    # Filter out cancelled rows
    df_active = df[df['row_kind'] != 'cancelled'].copy()

    # Parse dates
    for col in ['Delivered Date', 'Requested Date']:
        df_active[col] = pd.to_datetime(df_active[col], errors='coerce')

    # Determine delivered lines: rows where Delivered Date is not null
    # and status indicates delivery (not in-transit/pending statuses)
    in_transit_statuses = {
        'in transit', 'out for delivery', 'picked up', 'exception',
        'delivery exception', 'delayed', 'tendered', 'booked', 'dispatched',
        'pending', 'shipped', 'partially shipped', 'backordered',
        'short shipped', 'open', 'allocated', 'released', 'picked', 'packed'
    }

    df_active['status_lower'] = df_active['Status'].str.lower().str.strip()

    # OTIF (order) definition:
    # Denominator: distinct orders where delivered on time OR still in transit
    # (days_before_promise >= 0 OR days_late > 0 OR days_past_due > 0 AND status in transit set)
    # Numerator: denominator orders MINUS orders where any line is late OR short shipped

    # A line is "in scope" for OTIF order if:
    # (days_before_promise >= 0 OR days_late > 0) OR (days_past_due > 0 AND status in transit)
    def is_in_scope(row):
        dbp = row.get('days_before_promise', None)
        dl = row.get('days_late', None)
        dpd = row.get('days_past_due', None)
        st = row.get('status_lower', '')
        cond_delivered = (pd.notna(dbp) and dbp >= 0) or (pd.notna(dl) and dl > 0)
        cond_transit = (pd.notna(dpd) and dpd > 0) and (st in in_transit_statuses)
        return cond_delivered or cond_transit

    def is_otif_fail(row):
        dbp = row.get('days_before_promise', None)
        dl = row.get('days_late', None)
        dpd = row.get('days_past_due', None)
        smo = row.get('shipped_minus_ordered', None)
        st = row.get('status_lower', '')
        cond_delivered = (pd.notna(dbp) and dbp >= 0) or (pd.notna(dl) and dl > 0)
        cond_transit = (pd.notna(dpd) and dpd > 0) and (st in in_transit_statuses)
        in_scope = cond_delivered or cond_transit
        if not in_scope:
            return False
        late = pd.notna(dl) and dl > 0
        short = pd.notna(smo) and smo < 0 and (pd.notna(dbp) and dbp >= 0)
        return late or short

    df_active['_in_scope'] = df_active.apply(is_in_scope, axis=1)
    df_active['_otif_fail'] = df_active.apply(is_otif_fail, axis=1)

    warehouses = df_active['Warehouse'].dropna().unique()
    otif_order_results = []

    for wh in sorted(warehouses):
        wh_df = df_active[df_active['Warehouse'] == wh]
        scope_orders = set(wh_df[wh_df['_in_scope']]['Order ID'].unique())
        fail_orders = set(wh_df[wh_df['_otif_fail']]['Order ID'].unique())
        denom = len(scope_orders)
        numer = len(scope_orders - fail_orders)
        rate = numer / denom if denom > 0 else float('nan')
        otif_order_results.append({"name": str(wh), "value": round(rate, 6)})

    # Overall OTIF order
    scope_orders_all = set(df_active[df_active['_in_scope']]['Order ID'].unique())
    fail_orders_all = set(df_active[df_active['_otif_fail']]['Order ID'].unique())
    denom_all = len(scope_orders_all)
    numer_all = len(scope_orders_all - fail_orders_all)
    overall_rate = numer_all / denom_all if denom_all > 0 else float('nan')
    otif_order_results.append({"name": "Overall", "value": round(overall_rate, 6)})

    result['segments'].append({
        "segment_column": "Warehouse",
        "metric_column": "Order ID",
        "aggregation": "ratio",
        "label": "otif_order",
        "results": otif_order_results
    })

    result['assumptions'].append(
        "OTIF (order): an order passes only when every in-scope line is on-time AND shipped in full; cancelled rows excluded."
    )
    result['assumptions'].append(
        "In-scope lines: delivered (days_before_promise>=0 or days_late>0) OR still in transit (days_past_due>0 and status in transit set)."
    )

except Exception as e:
    result['segments'].append({
        "segment_column": "Warehouse",
        "metric_column": "Order ID",
        "aggregation": "ratio",
        "label": "otif_order",
        "results": [{"name": "error", "value": -1.0}]
    })
    result['assumptions'].append(f"OTIF order segmentation failed: {str(e)[:120]}")

