import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    # Filter out cancelled rows
    df_active = df[df['row_kind'] != 'cancelled'].copy()

    # Parse dates
    for col in ['Delivered Date', 'Requested Date']:
        df_active[col] = pd.to_datetime(df_active[col], errors='coerce')

    last_date = df_active['Delivered Date'].max()

    # Define delivered lines
    delivered_mask = df_active['Delivered Date'].notna() & (df_active['Status'].str.lower() == 'delivered')

    # In-transit statuses
    in_transit_statuses = [
        'in transit', 'out for delivery', 'picked up', 'exception', 'delivery exception',
        'delayed', 'tendered', 'booked', 'dispatched', 'pending', 'shipped',
        'partially shipped', 'backordered', 'short shipped', 'open', 'allocated',
        'released', 'picked', 'packed'
    ]

    # OTIF (order) logic per domain rules:
    # Denominator: distinct orders where (days_before_promise >= 0 OR days_late > 0 OR days_past_due > 0 AND status in transit)
    # i.e., delivered lines + in-transit lines
    # Numerator: denominator orders MINUS orders where any line fails OTIF
    # OTIF line = delivered on time AND shipped in full

    df_active['_status_lower'] = df_active['Status'].str.lower().str.strip()

    # Eligible lines: delivered or in-transit
    delivered_lines = df_active[delivered_mask].copy()
    intransit_lines = df_active[df_active['_status_lower'].isin(in_transit_statuses)].copy()

    # Denominator orders: orders with at least one delivered or in-transit line
    denom_orders = set(delivered_lines['Order ID']).union(set(intransit_lines['Order ID']))

    # For OTIF order: an order is OTIF if every delivered line is on time AND in full
    # On time: days_before_promise >= 0 (delivered on or before promised)
    # In full: shipped_minus_ordered >= 0

    # Per delivered line: is it OTIF?
    delivered_lines['_line_otif'] = (
        (delivered_lines['days_before_promise'] >= 0) &
        (delivered_lines['shipped_minus_ordered'] >= 0)
    )

    # Per order: all delivered lines must be OTIF
    order_otif = delivered_lines.groupby('Order ID')['_line_otif'].all()
    otif_orders = set(order_otif[order_otif].index)

    # Now compute by warehouse
    # Need warehouse per order — use first warehouse per order from active rows
    order_warehouse = df_active[df_active['Order ID'].isin(denom_orders)].groupby('Order ID')['Warehouse'].first()

    warehouses = order_warehouse.unique()
    otif_results = []

    for wh in sorted(warehouses):
        wh_orders = set(order_warehouse[order_warehouse == wh].index)
        wh_denom = len(wh_orders.intersection(denom_orders))
        wh_numer = len(wh_orders.intersection(otif_orders))
        if wh_denom > 0:
            otif_rate = wh_numer / wh_denom
        else:
            otif_rate = 0.0
        otif_results.append({"name": str(wh), "value": round(otif_rate, 6)})

    # Overall OTIF order rate
    overall_denom = len(denom_orders)
    overall_numer = len(otif_orders.intersection(denom_orders))
    overall_rate = overall_numer / overall_denom if overall_denom > 0 else 0.0
    otif_results.append({"name": "Overall", "value": round(overall_rate, 6)})

    result['segments'].append({
        "segment_column": "Warehouse",
        "metric_column": "Order ID",
        "aggregation": "ratio",
        "label": "otif_order",
        "results": otif_results
    })

    result['assumptions'].append(
        "OTIF (order): order is OTIF if every delivered line has days_before_promise >= 0 AND shipped_minus_ordered >= 0; denominator = distinct orders with at least one delivered or in-transit line."
