import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    active = df[
        (df['row_kind'] != 'cancelled') &
        (df['Currency'] == 'USD')
    ].copy()

    cost_per_lb_by_mode = (
        active[active['Weight'] > 0][['Mode', 'Total Charge', 'Weight']]
        .groupby('Mode')
        .agg(total_charge=('Total Charge', 'sum'), total_weight=('Weight', 'sum'))
        .assign(cost_per_lb=lambda x: x['total_charge'] / x['total_weight'])
        .reset_index()
    )

    cpl_results = [
        {"name": str(row['Mode']), "value": round(float(row['cost_per_lb']), 4)}
        for _, row in cost_per_lb_by_mode.iterrows()
    ]

    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "Total Charge",
        "aggregation": "ratio",
        "label": "cost_per_lb",
        "results": cpl_results
    })

    tc_by_mode = (
        active.groupby('Mode')['Total Charge']
        .sum()
        .reset_index()
        .sort_values('Total Charge', ascending=False)
    )
    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "Total Charge",
        "aggregation": "sum",
        "label": None,
        "results": [
            {"name": str(r['Mode']), "value": round(float(r['Total Charge']), 2)}
            for _, r in tc_by_mode.iterrows()
        ]
    })

    w_by_mode = (
        active[active['Weight'] > 0]
        .groupby('Mode')['Weight']
        .sum()
        .reset_index()
        .sort_values('Weight', ascending=False)
    )
    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "Weight",
        "aggregation": "sum",
        "label": None,
        "results": [
            {"name": str(r['Mode']), "value": round(float(r['Weight']), 2)}
            for _, r in w_by_mode.iterrows()
        ]
    })

    uom_by_mode = (
        active.groupby(['Mode', 'Weight UOM'])
        .size()
        .reset_index(name='count')
        .sort_values('count', ascending=False)
    )
    result['segments'].append({
        "segment_column": "Mode|Weight UOM",
        "metric_column": "Weight UOM",
        "aggregation": "count",
        "label": None,
        "results": [
            {"name": f"{r['Mode']}|{r['Weight UOM']}", "value": float(r['count'])}
            for _, r in uom_by_mode.iterrows()
        ]
    })

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

result['assumptions'].append("cost_per_lb = sum(Total Charge) / sum(Weight) for USD, non-cancelled rows with Weight > 0")
result['assumptions'].append("Cancelled rows (row_kind='cancelled') and non-USD rows excluded from all segment metrics")
result['assumptions'].append("Weight UOM breakdown uses Mode|Weight UOM joint segment to show unit mix per mode")

