import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    base = df[
        (df['row_kind'] != 'cancelled') &
        (df['Currency'] == 'USD')
    ].copy()

    valid_transit = base[base['transit_days'] >= 0].copy()

    mode_transit = (
        valid_transit.groupby('Mode')
        .apply(lambda g: g['transit_days'].sum() / g['Shipment ID'].nunique())
        .reset_index()
        .rename(columns={0: 'avg_transit_days'})
    )

    mode_transit_results = [
        {"name": str(row['Mode']), "value": round(float(row['avg_transit_days']), 4)}
        for _, row in mode_transit.iterrows()
    ]

    overall_avg = valid_transit['transit_days'].sum() / valid_transit['Shipment ID'].nunique()

    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "transit_days",
        "aggregation": "ratio",
        "label": "avg_transit_days",
        "results": mode_transit_results + [{"name": "Overall", "value": round(float(overall_avg), 4)}]
    })

except Exception as e:
    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "transit_days",
        "aggregation": "ratio",
        "label": "avg_transit_days",
        "results": [{"name": "error", "value": -1.0}]
    })

try:
    on_time_base = base[base['Status'].str.lower().isin(['delivered', 'returned to sender'])].copy()

    def on_time_rate(g):
        delivered = g[g['Status'].str.lower() == 'delivered']
        on_time = delivered[delivered['days_before_promise'] >= 0]
        denom = len(g)
        if denom == 0:
            return float('nan')
        return len(on_time) / denom

    mode_ot = (
        on_time_base.groupby('Mode')
        .apply(on_time_rate)
        .reset_index()
        .rename(columns={0: 'on_time_rate'})
    )

    mode_ot_results = [
        {"name": str(row['Mode']), "value": round(float(row['on_time_rate']), 4)}
        for _, row in mode_ot.iterrows()
        if not (row['on_time_rate'] != row['on_time_rate'])
    ]

    overall_ot_denom = len(on_time_base)
    overall_ot_num = len(on_time_base[
        (on_time_base['Status'].str.lower() == 'delivered') &
        (on_time_base['days_before_promise'] >= 0)
    ])
    overall_ot = overall_ot_num / overall_ot_denom if overall_ot_denom > 0 else float('nan')

    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "days_before_promise",
        "aggregation": "ratio",
        "label": "on_time_rate",
        "results": mode_ot_results + [{"name": "Overall", "value": round(float(overall_ot), 4)}]
    })

except Exception:
    pass

try:
    mode_charge = (
        base.groupby('Mode')['Total Charge']
        .mean()
        .reset_index()
        .rename(columns={'Total Charge': 'mean_total_charge'})
    )

    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "Total Charge",
        "aggregation": "mean",
        "label": None,
        "results": [
            {"name": str(row['Mode']), "value": round(float(row['mean_total_charge']), 4)}
            for _, row in mode_charge.iterrows()
        ]
    })

except Exception:
    pass

result['assumptions'].append("avg_transit_days = sum(transit_days) / distinct shipments where transit_days >= 0, USD non-cancelled rows only")
